import {createState,MISSIONS,norm,burn,step,score} from './sim.js';
import {createScene} from './scene.js';
const $=id=>document.getElementById(id);let state=createState(),keys={},scene,sound=false,audioCtx,toastTimer,last=performance.now(),lastUi=0,previousStage=0,previousStatus='flying',lastFuelWarning=false,view='orbit',manualWarn=false,dialogWasPaused=false;
const stageNames=['轨道转移','交会接近','精密对接'];const hints=['调整右侧机动参数并点火，或启用自动交会辅助。','目标已进入近场。提前制动，留意速度与剩余推进剂。','低速靠近前向端口。速度 < 0.15 m/s，姿态误差 < 5°。'];
const clock=t=>[Math.floor(t/3600),Math.floor(t/60)%60,Math.floor(t)%60].map(x=>String(x).padStart(2,'0')).join(':');
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000);}
function ping(freq=640){if(!sound)return;try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.25);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.25);}catch{}}
function communicate(msg){$('comms-message').textContent=msg;$('comms-time').textContent=clock(state.time).slice(3);ping();}
const getDV=()=>[+$('radial').value,+$('prograde').value,+$('normal').value];
function updatePlan(){for(const id of ['prograde','radial','normal']){const v=+$(id).value;$(id+'-out').innerHTML=(v>=0?'+':'−')+Math.abs(v).toFixed(2)+' <small>m/s</small>';}$('planned-dv').innerHTML=norm(getDV()).toFixed(2)+' <small>m/s</small>';$('planned-fuel').innerHTML=(norm(getDV())*1.3).toFixed(1)+' <small>%</small>';}
for(const id of['prograde','radial','normal'])$(id).addEventListener('input',updatePlan);
function setView(next){view=next;scene?.setView(next);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===next));$('dock-hud').hidden=next!=='dock';$('scene-caption').textContent=next==='orbit'?'地球低轨道':next==='chase'?'飞行器外部视角':'前向对接摄像机';$('scene-scale').textContent=next==='orbit'?'轨迹示意 · 比例已增强':'局部相对坐标 · m';$('scene-help').textContent=next==='dock'?'方向键调整姿态 · WASD / R F 平移':'拖拽旋转视角 · 滚轮缩放';}
function executeBurn(){if(state.status!=='flying')return;if(state.paused){toast('请先继续任务，再执行点火。');return;}if(burn(state,getDV())){communicate('机动点火已完成。航天器现在自由滑行；接近目标前请主动制动。');toast('点火完成 · Δv '+norm(getDV()).toFixed(2)+' m/s');ping(400);updateUI();}else toast('推进剂不足，或计划速度增量为零。');}
function toggleAuto(){if(state.status!=='flying')return;if(state.fuel<=0){toast('推进剂已耗尽，无法启动辅助推进。');return;}if(state.assistUsed>=MISSIONS[state.mission].assist){toast('本任务的 20 秒辅助额度已用完，请手动接管。');return;}state.autopilot=!state.autopilot;state.braking=false;communicate(state.autopilot?'自动交会接管。将依次完成接近、制动与姿态对准，手动输入可随时接管。':'自动交会已解除。逐梦者，现在由你掌舵。');updateUI();}
function brake(){if(state.status!=='flying')return;state.braking=!state.braking;state.autopilot=false;toast(state.braking?'相对制动中 · 持续消耗推进剂':'相对制动已取消');updateUI();}
function precision(){state.precision=!state.precision;updateUI();}
function togglePause(){if(state.status!=='flying')return;state.paused=!state.paused;keys={};updateUI();}
function setWarp(w){if(state.status!=='flying')return;const d=norm(state.r),max=d<30?1:d<200?5:20;if(w>max){toast('当前距离的最大安全时间倍率为 '+max+'×');return;}state.warp=w;updateUI();}
function reset(mission=state.mission){state=createState(mission);keys={};previousStage=-1;previousStatus='flying';lastFuelWarning=false;const m=MISSIONS[mission];$('mission-id').textContent=m.id;$('mission-title').textContent=m.title;$('mission-subtitle').textContent=m.description;$('mission-badge').innerHTML='<i></i> 任务进行中';dialogWasPaused=false;$('prograde').value=mission==='night'?.30:2.04;$('radial').value=mission==='night'?-.08:-1.14;$('normal').value=mission==='night'?-.05:-.08;updatePlan();setView(mission==='night'?'chase':'orbit');document.querySelectorAll('dialog[open]').forEach(d=>d.close());communicate(mission==='night'?'已进入地影。请依靠对接仪表保持进场轴线，辅助飞控剩余 20 秒。':'逐梦者，遥测信号稳定。曙光空间站已开放 01 号对接口，祝飞行顺利。');updateUI();}
function updateUI(){const d=norm(state.r),speed=norm(state.v),angle=Math.hypot(state.yaw,state.pitch);$('distance').innerHTML=(d>=1000?(d/1000).toFixed(2):d.toFixed(1))+' <small>'+(d>=1000?'km':'m')+'</small>';$('speed').innerHTML=speed.toFixed(2)+' <small>m/s</small>';$('speed').style.color=d<30&&speed>.15?'#e9b86b':'';$('alignment').innerHTML=angle.toFixed(1)+' <small>°</small>';$('fuel-text').innerHTML=state.fuel.toFixed(1)+' <small>%</small>';$('fuel-meter').style.width=state.fuel+'%';$('mobile-fuel').textContent='燃料 '+state.fuel.toFixed(1)+'%';$('fuel-meter').style.background=state.fuel<20?'#e9b86b':'';$('remaining-dv').innerHTML=(state.fuel/1.3).toFixed(1)+' <small>m/s</small>';$('mission-time').textContent=clock(state.time);$('altitude').innerHTML=(398.6+state.r[0]/1000).toFixed(1)+' <small>km</small>';$('altitude-caption').textContent=(398.6+state.r[0]/1000).toFixed(1)+' KM';$('pause').textContent=state.paused?'▶':'Ⅱ';if(state.status==='flying')$('mission-badge').innerHTML=state.paused?'Ⅱ 任务已暂停':'<i></i> 任务进行中';$('pause').setAttribute('aria-label',state.paused?'继续':'暂停');$('precision-status').textContent=state.precision?'开':'关';$('precision-status').style.color=state.precision?'#79ebc4':'';$('thrust-mode').textContent=state.precision?'精细 RCS':'标准 RCS';$('attitude-readout').textContent=`俯仰 ${state.pitch>=0?'+':''}${state.pitch.toFixed(1)}° · 偏航 ${state.yaw>=0?'+':''}${state.yaw.toFixed(1)}°`;$('autopilot').classList.toggle('engaged',state.autopilot);$('autopilot').setAttribute('aria-pressed',state.autopilot);$('autopilot-label').textContent=state.autopilot?'自动交会运行中':'开启自动交会';$('brake').classList.toggle('engaged',state.braking);$('burn').disabled=state.status!=='flying'||state.paused||norm(getDV())*1.3>state.fuel;$('dock-hud-label').textContent=`横向偏差 ${Math.hypot(state.r[0],state.r[2]).toFixed(2)} m · ${state.capture>0?'捕获中 '+Math.min(100,Math.round(state.capture/2*100))+'%':'01 号对接口'}`;
 $('deadline').textContent=MISSIONS[state.mission].limit?'剩余 '+clock(Math.max(0,MISSIONS[state.mission].limit-state.time)).slice(3):'MET';$('assist-note').textContent=state.mission==='night'?'辅助额度剩余 '+Math.max(0,20-state.assistUsed).toFixed(1)+' 秒':'辅助飞控会持续消耗推进剂';
 document.querySelectorAll('[data-warp]').forEach(b=>b.classList.toggle('selected',+b.dataset.warp===state.warp));document.querySelectorAll('[data-control]').forEach(b=>b.classList.toggle('pressed',!!keys[b.dataset.control]));
 if(previousStage!==state.stage){document.querySelectorAll('[data-stage]').forEach(el=>{const n=+el.dataset.stage;el.classList.toggle('current',n===state.stage);el.classList.toggle('done',n<state.stage);el.querySelector('.step-dot').textContent=n<state.stage?'✓':n+1;el.querySelector('.step-state')?.remove();if(n===state.stage){const span=document.createElement('span');span.className='step-state';span.textContent='正在执行';el.querySelector('div').appendChild(span);}});$('step-count').textContent='0'+(state.stage+1)+' / 03';$('objective-hint').querySelector('p').textContent=hints[state.stage];if(previousStage>=0){communicate(state.stage===1?'交会目标已确认，距离小于 200 米。时间倍率已限制，准备进场。':'进入精密对接段。请将速度降至 0.15 m/s 以下，对准 01 号端口。');toast('进入'+stageNames[state.stage]);if(state.stage===2&&view==='orbit')setView('chase');}previousStage=state.stage;}
 if(state.fuel<10&&!lastFuelWarning){communicate('推进剂低于 10%。请减少不必要的机动，保留制动余量。');lastFuelWarning=true;}
 if(state.status!==previousStatus&&state.status!=='flying')finish();previousStatus=state.status;
}
function records(){let r={};try{r=JSON.parse(localStorage.getItem('orbital-records')||'{}')}catch{}return r;}
function openMissions(){const r=records();document.querySelectorAll('[data-record]').forEach(el=>el.textContent='最佳成绩 '+(r[el.dataset.record]??'—'));openDialog('missions-dialog');}
function openDialog(id){keys={};dialogWasPaused=state.paused;if(state.status==='flying')state.paused=true;$(id).showModal();updateUI();}
function finish(){keys={};state.autopilot=false;state.braking=false;const success=state.status==='docked',value=score(state);$('mission-badge').innerHTML=success?'<i></i> 对接完成':'任务已结束';$('result-symbol').textContent=success?'◎':'⊘';$('result-eyebrow').textContent=success?'DOCKING COMPLETE':'MISSION ENDED';$('result-title').textContent=success?'欢迎来到曙光。':'调整航线，再次出发。';$('result-message').textContent=success?'对接锁已闭合。你的旅程，为星辰之间多了一次相遇。':state.reason;$('result-score').innerHTML=success?value+' <small>任务评分 / 1000</small>':'— <small>任务未完成</small>';$('result-time').textContent=clock(state.time);$('result-fuel').textContent=state.fuel.toFixed(1)+'%';$('result-grade').textContent=success?(value>=900?'S':value>=800?'A':'B'):'—';if(success){const r=records();r[state.mission]=Math.max(value,r[state.mission]||0);try{localStorage.setItem('orbital-records',JSON.stringify(r));}catch{}communicate('软捕获完成！曙光空间站欢迎逐梦者，任务圆满完成。');}else communicate(state.reason);$('result-dialog').showModal();ping(success?880:220);}
$('burn').onclick=executeBurn;$('autopilot').onclick=toggleAuto;$('brake').onclick=brake;$('precision').onclick=precision;$('pause').onclick=togglePause;$('restart').onclick=()=>reset();$('guide-open').onclick=()=>openDialog('guide-dialog');$('shortcuts').onclick=()=>openDialog('guide-dialog');$('missions-open').onclick=openMissions;$('flight-tab').onclick=()=>document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('next-mission').onclick=()=>{$('result-dialog').close();openMissions();};$('retry-result').onclick=()=>reset();$('reset-camera').onclick=()=>scene?.resetCamera();$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.querySelector('.space-panel').requestFullscreen?.().catch(()=>toast('当前浏览器不支持全屏模式。'));};$('sound').onclick=()=>{sound=!sound;$('sound').style.color=sound?'#79ebc4':'';$('sound').setAttribute('aria-label',sound?'关闭声音':'开启声音');toast(sound?'任务提示音已开启':'任务提示音已关闭');ping();};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{if(state.status==='flying'&&!document.querySelector('dialog[open]'))state.paused=dialogWasPaused;keys={};updateUI();}));document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>reset(b.dataset.mission));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-warp]').forEach(b=>b.onclick=()=>setWarp(+b.dataset.warp));
const movement=['KeyW','KeyA','KeyS','KeyD','KeyR','KeyF','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'];
function keyDown(code){keys[code]=true;if(state.autopilot){state.autopilot=false;toast('手动接管 · 自动交会已解除');}state.braking=false;}
document.querySelectorAll('[data-control]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keyDown(b.dataset.control);});for(const type of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>{keys[b.dataset.control]=false;});});
addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.target.closest('input,textarea,select,[contenteditable=true]'))return;if((e.code==='Enter'||e.code==='Space')&&e.target.closest('button,a'))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)togglePause();return;}if(movement.includes(e.code)){e.preventDefault();keyDown(e.code);return;}if(e.repeat)return;if(e.code==='Enter'){e.preventDefault();executeBurn();}if(e.code==='KeyX')brake();if(e.code==='KeyP')precision();if(e.code==='KeyC'){const views=['orbit','chase','dock'];setView(views[(views.indexOf(view)+1)%3]);}if(e.key==='?')openDialog('guide-dialog');});addEventListener('keyup',e=>{keys[e.code]=false;});addEventListener('blur',()=>{keys={};if(state.status==='flying'){state.paused=true;updateUI();}});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys={};state.paused=true;updateUI();}});
try{scene=createScene($('scene'));$('scene-loading').hidden=true;}catch(e){$('scene-loading').innerHTML='3D 视图未能启动。请开启浏览器硬件加速后刷新。';console.error(e);}
function animate(now){const dt=Math.min(.08,(now-last)/1000);last=now;const wasAuto=state.autopilot;let remaining=dt*state.warp;while(remaining>0){const h=Math.min(remaining,.025);step(state,h,keys);remaining-=h;}if(wasAuto&&!state.autopilot&&state.assistUsed>=MISSIONS[state.mission].assist){communicate('辅助额度已用完。请立即手动接管，使用 X 提前制动。');toast('20 秒辅助结束 · 请手动接管');}scene?.update(state,getDV(),now);if(now-lastUi>80){updateUI();lastUi=now;}requestAnimationFrame(animate);}
updatePlan();updateUI();requestAnimationFrame(animate);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_flight_state',description:'Read the spacecraft relative position, velocity, fuel, mission stage and control modes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mission:state.mission,position:state.r,velocity:state.v,fuel:state.fuel,stage:state.stage,status:state.status,autopilot:state.autopilot,paused:state.paused})});document.modelContext.registerTool({name:'set_maneuver_plan',description:'Stage the three velocity increments in the visible maneuver planner without executing a burn.',inputSchema:{type:'object',properties:{radial:{type:'number',minimum:-5,maximum:5},prograde:{type:'number',minimum:-5,maximum:5},normal:{type:'number',minimum:-2,maximum:2}},required:['radial','prograde','normal'],additionalProperties:false},execute:input=>{for(const key of['radial','prograde','normal']){if(typeof input[key]!=='number'||!Number.isFinite(input[key])||Math.abs(input[key])>(key==='normal'?2:5))throw new Error('Invalid maneuver value: '+key);}for(const key of['radial','prograde','normal'])$(key).value=input[key];updatePlan();return{plannedDV:getDV(),total:norm(getDV()),executed:false};}});}catch(e){console.warn('WebMCP unavailable',e);}}
